import "../../styles/index-base.css";
import "../../styles/components/table.css";
import type { HTMLAttributes, TableHTMLAttributes, TdHTMLAttributes, ThHTMLAttributes } from "react";
import { cn } from "../../lib/cn";

export type TableProps = TableHTMLAttributes<HTMLTableElement> & {
  containerClassName?: string;
};

export function Table({ className, containerClassName, ...props }: TableProps) {
  return <div className={cn("ix-table__container", containerClassName)}><table className={cn("ix-table", className)} {...props} /></div>;
}

export function TableHeader({ className, ...props }: HTMLAttributes<HTMLTableSectionElement>) {
  return <thead className={cn("ix-table__header", className)} {...props} />;
}

export function TableBody({ className, ...props }: HTMLAttributes<HTMLTableSectionElement>) {
  return <tbody className={cn("ix-table__body", className)} {...props} />;
}

export function TableFooter({ className, ...props }: HTMLAttributes<HTMLTableSectionElement>) {
  return <tfoot className={cn("ix-table__footer", className)} {...props} />;
}

export function TableRow({ className, ...props }: HTMLAttributes<HTMLTableRowElement>) {
  return <tr className={cn("ix-table__row", className)} {...props} />;
}

export function TableHead({ className, scope = "col", ...props }: ThHTMLAttributes<HTMLTableCellElement>) {
  return <th className={cn("ix-table__head", className)} scope={scope} {...props} />;
}

export function TableCell({ className, ...props }: TdHTMLAttributes<HTMLTableCellElement>) {
  return <td className={cn("ix-table__cell", className)} {...props} />;
}

export function TableCaption({ className, ...props }: HTMLAttributes<HTMLTableCaptionElement>) {
  return <caption className={cn("ix-table__caption", className)} {...props} />;
}

/* Generated from src/styles.css. Do not edit directly. */

@layer index.tokens, index.base, index.components;

@layer index.components {
.ix-table__container {
  scrollbar-color: var(--ix-scrollbar-thumb) transparent;
  scrollbar-width: thin;
}

.ix-table__container::-webkit-scrollbar { width: 10px; height: 10px; }

.ix-table__container::-webkit-scrollbar-track { background: transparent; }

.ix-table__container::-webkit-scrollbar-thumb {
  border: 3px solid transparent;
  border-radius: 999px;
  background: var(--ix-scrollbar-thumb);
  background-clip: padding-box;
}

.ix-table__container::-webkit-scrollbar-thumb:hover { background: var(--ix-scrollbar-thumb-hover); background-clip: padding-box; }

@media (forced-colors: active) {
.ix-table__container { scrollbar-color: auto; }
}

.ix-table__container { width: 100%; overflow: auto; border: 1px solid var(--ix-control-border); border-radius: var(--ix-radius-container); background: var(--ix-bg-surface); }

.ix-table { width: 100%; min-width: 560px; border-collapse: separate; border-spacing: 0; color: var(--ix-fg-default); font-size: var(--ix-type-label); font-variant-numeric: tabular-nums; }

.ix-table__caption { padding: 10px 12px; color: var(--ix-fg-subtle); text-align: left; caption-side: bottom; }

.ix-table__head { height: 34px; padding: 0 12px; border-bottom: 1px solid var(--ix-separator); background: var(--ix-bg-stage); color: var(--ix-fg-subtle); font-size: var(--ix-type-metadata); font-weight: 560; text-align: left; white-space: nowrap; }

.ix-table__cell { height: var(--ix-row-height-table); padding: 0 12px; border-bottom: 1px solid var(--ix-separator); color: var(--ix-fg-muted); vertical-align: middle; }

.ix-table__row:last-child .ix-table__cell { border-bottom: 0; }

.ix-table__row[data-selected] { background: var(--ix-selected); }

.ix-table__footer .ix-table__cell { background: var(--ix-bg-stage); color: var(--ix-fg-default); font-weight: 560; }

@media (hover: hover) and (pointer: fine) {
.ix-table__body .ix-table__row:hover { background: var(--ix-hover); }
}
}
